create schema s; create type s.mood as enum ('a', 'b'); create sequence s.seq; create macro s.m(x) as x > 0; create macro s.m2(x) as x + 1; create table main.p (id integer primary key, n integer, v varchar, n2 integer default s.m2(1), check (cast(v as s.mood) is not null)); create table main.c (id integer primary key, pid integer references main.p (id), k integer, check (s.m(k)));
